static Update Parse(const S&json,const S&id,const S&current,bool scoped){auto f=Json{json}.parse();Update u;S target=f[L"TargetClientCode"];if((scoped&&target!=id)||(!scoped&&!target.empty())||f[L"Component"]!=L"GLOBAL"||f[L"PetApiVersion"]!=L"1")return u;S url=f[L"PackageUrl"],prefix=L"https://github.com/lealinfopdvnovo/leal-info-pdv-updates/releases/download/v";if(url.rfind(prefix,0)!=0||url.find_first_of(L"\r\n\t ")!=S::npos)return u;S sha=f[L"Sha256"];if(sha.size()!=64||!std::all_of(sha.begin(),sha.end(),[](wchar_t c){return(c>=L'0'&&c<=L'9')||(c>=L'a'&&c<=L'f')||(c>=L'A'&&c<=L'F');}))return u;if(Version(f[L"Version"])<=Version(current))return u;u={f[L"Version"],sha,true};return u;}
