static bool Balloon(const S&title,const S&body){tray.uFlags=NIF_INFO;wcsncpy_s(tray.szInfoTitle,title.c_str(),_TRUNCATE);wcsncpy_s(tray.szInfo,body.c_str(),_TRUNCATE);tray.dwInfoFlags=NIIF_INFO|NIIF_RESPECT_QUIET_TIME;return Shell_NotifyIconW(NIM_MODIFY,&tray)!=FALSE;}
static bool LiaRouteEligible(const S&id,const S&current){return id==L"001"&&Version(current)>=Version(L"10.458");}
static void CheckNow(bool manual=false){if(manual)manualPending=true;if(busy.exchange(true))return;if(worker.joinable())worker.join();worker=std::thread([]{auto result=new Result;try{S current=InstalledVersion();if(route==L"CLIENT"){S feed=Fetch(L"clients/"+identity+L"/version.json");if(!feed.empty())result->update=ParseClient(feed,identity,current);if(LiaRouteEligible(identity,current)){S component=Fetch(L"clients/001/lia-voice/version.json");if(!component.empty()){auto extra=ParseClient(component,identity,current);if(extra.found&&(!result->update.found||Version(extra.version)>Version(result->update.version)))result->update=extra;}}}else{S global=Fetch(L"version.json"),scoped=Fetch(L"clients/"+identity+L"/global/version.json");if(!scoped.empty())result->update=Parse(scoped,identity,current,true);if(!result->update.found&&!global.empty())result->update=Parse(global,identity,current,false);}}catch(...){result->failed=true;}if(!PostMessageW(window,CheckResult,0,(LPARAM)result))delete result;});}
