static bool StartupEnabled(){return ReadIni(prefs,L"StartupEnabled",L"1")==L"1";}
static void ToggleStartup(){bool enable=!StartupEnabled();HKEY run=nullptr;if(RegCreateKeyExW(HKEY_CURRENT_USER,L"Software\\Microsoft\\Windows\\CurrentVersion\\Run",0,nullptr,0,KEY_SET_VALUE,nullptr,&run,nullptr)!=ERROR_SUCCESS)return;LONG status=ERROR_SUCCESS;if(enable){S command=L"\""+agent+L"\" --config \""+config+L"\"";status=RegSetValueExW(run,key.c_str(),0,REG_SZ,(const BYTE*)command.c_str(),(DWORD)((command.size()+1)*sizeof(wchar_t)));}else status=RegDeleteValueW(run,key.c_str());RegCloseKey(run);if(status==ERROR_SUCCESS||(!enable&&status==ERROR_FILE_NOT_FOUND))WritePrivateProfileStringW(L"Notifier",L"StartupEnabled",enable?L"1":L"0",prefs.c_str());}
