 if(msg==RegisterWindowMessageW(L"TaskbarCreated")){tray.uFlags=NIF_ICON|NIF_TIP|NIF_MESSAGE;trayRegistered=Shell_NotifyIconW(NIM_ADD,&tray)!=FALSE;CheckNow();return 0;}
